//! Database schema migrations, embedded from `install/migrations` and applied with `SQLx`.

use crate::config::Config;
use anyhow::{Context, Result, bail, ensure};
use sqlx::{
    Connection, PgConnection, SqlSafeStr,
    migrate::{AppliedMigration, Migrate, Migration, MigrationType, Migrator},
};
use std::{collections::BTreeSet, time::Duration};

// `BASELINE` and `SCHEMA_VERSION`, generated by `build.rs` from `install/migrations`.
include!(concat!(env!("OUT_DIR"), "/schema_version.rs"));

/// The `SQLx` table that records applied migrations.
const HISTORY_TABLE: &str = "_sqlx_migrations";
/// The history entry that stands for the retired migrations up to `BASELINE`.
const BASELINE_DESCRIPTION: &str = "baseline";
/// How long connecting to PostgreSQL may take.
const CONNECT_TIMEOUT: Duration = Duration::from_secs(10);
/// How long one migration statement may run.
const STATEMENT_TIMEOUT: Duration = Duration::from_hours(1);
/// How long a migration waits for a lock, so that it fails instead of stalling live queries.
const LOCK_TIMEOUT: Duration = Duration::from_secs(5);
/// How long a live query may wait for a migration's locks before the migration is cancelled. A
/// migration holds its locks until it commits, so a slow one can stall logins and games.
const MAX_BLOCKED_WAIT: Duration = Duration::from_secs(10);
/// How often `apply_watched` looks for queries that the migration blocks.
const BLOCKED_POLL_INTERVAL: Duration = Duration::from_secs(1);

/// The command that brings a database to `SCHEMA_VERSION`.
pub const APPLY_COMMAND: &str = "hanabi-live migrate apply";

fn migrator() -> Migrator {
    let mut migrator = sqlx::migrate!("../install/migrations");
    // Retired migrations stay in the history after their files are deleted.
    migrator.set_ignore_missing(true);
    // `apply` holds the lock itself, across schema installation too.
    migrator.set_locking(false);
    migrator
}

enum State {
    /// The database has no tables.
    Empty,
    /// The versions recorded in the `SQLx` history, in ascending order.
    History(Vec<AppliedMigration>),
}

async fn table_exists(connection: &mut PgConnection, table: &str) -> Result<bool> {
    let name = format!("public.{table}");
    Ok(
        sqlx::query_scalar!("SELECT to_regclass($1) IS NOT NULL AS \"exists!\"", name)
            .fetch_one(connection)
            .await?,
    )
}

async fn inspect(connection: &mut PgConnection) -> Result<State> {
    if table_exists(connection, HISTORY_TABLE).await? {
        if let Some(version) = connection.dirty_version(HISTORY_TABLE).await? {
            bail!("Migration {version} failed partway; repair the database before continuing");
        }
        let applied = connection.list_applied_migrations(HISTORY_TABLE).await?;
        let Some(current) = applied.last().map(|migration| migration.version) else {
            bail!(
                "Database has an empty migration history, older than baseline {BASELINE}; upgrade it with an earlier release first"
            );
        };
        ensure!(
            current >= BASELINE,
            "Database schema version {current} is older than baseline {BASELINE}; upgrade it with an earlier release first"
        );
        ensure!(
            current <= SCHEMA_VERSION,
            "Database schema version {current} is newer than this release's {SCHEMA_VERSION}; refusing a downgrade"
        );
        return Ok(State::History(applied));
    }
    let empty: bool = sqlx::query_scalar!(
        "SELECT NOT EXISTS (SELECT FROM information_schema.tables WHERE table_schema = 'public') AS \"empty!\""
    )
    .fetch_one(&mut *connection)
    .await?;
    ensure!(
        empty,
        "Database has tables but no migration history; install the schema into an empty database"
    );
    Ok(State::Empty)
}

/// Describes each step that `apply` would perform, in order.
fn pending(state: &State, migrator: &Migrator) -> Vec<String> {
    let applied: BTreeSet<_> = match state {
        State::Empty => {
            return vec![format!("install the schema at version {SCHEMA_VERSION}")];
        }
        State::History(applied) => applied.iter().map(|migration| migration.version).collect(),
    };
    migrator
        .iter()
        .filter(|migration| !applied.contains(&migration.version))
        .map(|migration| {
            format!(
                "migration {:03} {}",
                migration.version, migration.description
            )
        })
        .collect()
}

fn current_version(state: &State) -> String {
    match state {
        State::Empty => "none".into(),
        State::History(applied) => applied
            .last()
            .map_or(BASELINE, |migration| migration.version)
            .to_string(),
    }
}

/// Installs the schema into an empty database and records the baseline and every migration, which
/// the schema already contains, without running them.
async fn install(connection: &mut PgConnection, migrator: &Migrator) -> Result<()> {
    let mut transaction = connection.begin().await?;
    #[expect(
        clippy::disallowed_methods,
        reason = "the schema file has many statements, which the query macros cannot run"
    )]
    sqlx::raw_sql(include_str!("../../install/database_schema.sql"))
        .execute(&mut *transaction)
        .await
        .context("Unable to install the database schema")?;
    transaction.ensure_migrations_table(HISTORY_TABLE).await?;
    let baseline = Migration::new(
        BASELINE,
        BASELINE_DESCRIPTION.into(),
        MigrationType::Simple,
        "".into_sql_str(),
        false,
    );
    transaction.skip(HISTORY_TABLE, &baseline).await?;
    for migration in migrator.iter() {
        transaction.skip(HISTORY_TABLE, migration).await?;
    }
    transaction.commit().await?;
    Ok(())
}

/// Brings an empty or older database to `SCHEMA_VERSION`, then reports the steps performed.
pub async fn apply(connection: &mut PgConnection) -> Result<Vec<String>> {
    let migrator = migrator();
    connection.lock().await?;
    let state = inspect(connection).await?;
    let steps = pending(&state, &migrator);
    if matches!(state, State::Empty) {
        install(connection, &migrator).await?;
    }
    migrator.run(&mut *connection).await?;
    connection.unlock().await?;
    Ok(steps)
}

/// Runs `apply`, cancelling the statement in progress if a live query waits on the migration's
/// locks for longer than `MAX_BLOCKED_WAIT`. A migration in a transaction then rolls back.
async fn apply_watched(config: &Config, connection: &mut PgConnection) -> Result<Vec<String>> {
    let pid = sqlx::query_scalar!("SELECT pg_backend_pid() AS \"pid!\"")
        .fetch_one(&mut *connection)
        .await?;
    let mut watchdog = connect(config).await?;
    let applying = apply(connection);
    tokio::pin!(applying);
    let mut poll = tokio::time::interval(BLOCKED_POLL_INTERVAL);
    let blocked = loop {
        tokio::select! {
            result = &mut applying => {
                watchdog.close().await?;
                return result;
            }
            _ = poll.tick() => {
                let blocked = sqlx::query_scalar!(
                    "SELECT count(*) AS \"blocked!\" FROM pg_stat_activity
                     WHERE $1 = ANY(pg_blocking_pids(pid))
                         AND now() - query_start > make_interval(secs => $2)",
                    pid,
                    MAX_BLOCKED_WAIT.as_secs_f64()
                )
                .fetch_one(&mut watchdog)
                .await?;
                if blocked > 0 {
                    break blocked;
                }
            }
        }
    };
    sqlx::query_scalar!("SELECT pg_cancel_backend($1) AS \"cancelled!\"", pid)
        .fetch_one(&mut watchdog)
        .await?;
    watchdog.close().await?;
    let error = match applying.await {
        // The cancellation arrived between statements, after the last migration.
        Ok(steps) => return Ok(steps),
        Err(error) => error,
    };
    Err(error.context(format!(
        "Cancelled the migration because {blocked} live queries waited more than {} seconds for its locks",
        MAX_BLOCKED_WAIT.as_secs()
    )))
}

/// Refuses to serve a database that is not exactly at `SCHEMA_VERSION`.
pub(crate) async fn require_current(connection: &mut PgConnection) -> Result<()> {
    let state = inspect(connection).await?;
    ensure!(
        matches!(state, State::History(_)) && pending(&state, &migrator()).is_empty(),
        "Server requires database schema version {SCHEMA_VERSION}; run `{APPLY_COMMAND}`"
    );
    Ok(())
}

pub async fn connect(config: &Config) -> Result<PgConnection> {
    let options = config.database_options().options([
        (
            "statement_timeout",
            STATEMENT_TIMEOUT.as_millis().to_string(),
        ),
        ("lock_timeout", LOCK_TIMEOUT.as_millis().to_string()),
    ]);
    tokio::time::timeout(CONNECT_TIMEOUT, PgConnection::connect_with(&options))
        .await
        .context("Timed out connecting to PostgreSQL")?
        .context("Unable to connect to PostgreSQL")
}

/// Runs `hanabi-live migrate status` or `hanabi-live migrate apply`.
pub async fn run(config: &Config, apply_pending: bool) -> Result<()> {
    let mut connection = connect(config).await?;
    if apply_pending {
        let steps = apply_watched(config, &mut connection).await?;
        for step in &steps {
            println!("Applied: {step}");
        }
        println!("Database schema is at version {SCHEMA_VERSION}.");
    } else {
        let state = inspect(&mut connection).await?;
        println!(
            "Database schema version: {}; this release requires {SCHEMA_VERSION}.",
            current_version(&state)
        );
        let steps = pending(&state, &migrator());
        if steps.is_empty() {
            println!("No pending migrations.");
        }
        for step in steps {
            println!("Pending: {step}");
        }
    }
    connection.close().await?;
    Ok(())
}
